export class Capturing extends LitElement {
 static get observedAttributes(){return [...super.observedAttributes,"padding","padding-inline"];}
 /** @attribute padding */ @atomState() declare padding:string|undefined;
 /** @attribute padding-inline */ @atomState() declare paddingInline:string|undefined;
 /** @internal */ @atomState() declarationOrder:string[]=[];
 private initialAttributes=new Map<string,string>();
 constructor(){
  super();
  const keys=Object.keys(this).filter(k=>["padding","paddingInline"].includes(k));
  const properties=keys.map(k=>[k,(this as any)[k]] as const);
  for(const key of keys)delete (this as any)[key];
  for(const a of [...this.attributes])if(["padding","padding-inline"].includes(a.name)){
